// Helper function to call Gemini with model cascade and retry for high demand
async function generateCognitiveWithCascade(ai: GoogleGenAI, prompt: string): Promise<any> {
  const models = ['gemini-3.8-flash', 'gemini-flash-latest', 'gemini-3.1-flash-lite'];
  let lastErr: any = null;

  for (const modelName of models) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const response = await ai.models.generateContent({
          model: modelName,
          contents: prompt,
          config: {
            responseMimeType: 'application/json',
          },
        });

        const text = response.text || '';
        if (text) {
          const parsed = JSON.parse(text);
          return { analysis: parsed, modelUsed: modelName };
        }
      } catch (err: any) {
        lastErr = err;
        const msg = err?.message || String(err);
        const isTransient =
          msg.includes('503') ||
          msg.includes('high demand') ||
          msg.includes('429') ||
          msg.includes('UNAVAILABLE') ||
          msg.includes('RESOURCE_EXHAUSTED');

        console.warn(`[Cognitive Advisor] Model ${modelName} (attempt ${attempt + 1}) notice: ${msg}`);

        if (isTransient && attempt === 0) {
          // Wait 1 second before retrying
          await new Promise((r) => setTimeout(r, 1000));
          continue;
        }
        break; // try next model in cascade
      }
    }
  }

  throw lastErr || new Error('Servicio de IA en alta demanda temporal');
}

// AI Cognitive Analysis API
app.post('/api/advisor/analyze', async (req, res) => {
  const { cityData } = req.body;
  if (!cityData) {
    return res.status(400).json({ error: 'Faltan datos de la ciudad para el análisis cognitivo' });
  }

  const ai = getGeminiClient();

  // If Gemini API is not configured, fall back to heuristic analyzer directly
  if (!ai) {
    const fallback = analyzePlaystyleHeuristics(cityData);
    return res.json({
      usedAI: false,
      message: 'Gemini API no configurada en el servidor; utilizando motor heurístico cognitivo local',
      analysis: fallback,
    });
  }

  const prompt = `Actúa como un renombrado urbanista, planificador regional y psicólogo de juego de SimCity 1989.
Analiza la siguiente metrópolis del jugador y diagnostica su estilo cognitivo de juego:
- Nombre de la ciudad: ${cityData.name}
- Año: ${cityData.year}
- Población: ${cityData.stats?.population} (R: ${cityData.stats?.resPop}, C: ${cityData.stats?.comPop}, I: ${cityData.stats?.indPop})
- Fondos del tesoro: $${cityData.funds}
- Tasa de impuestos: ${cityData.budget?.taxRate}%
- Aprobación ciudadana: ${cityData.stats?.approvalRating}%
- Polución media: ${cityData.stats?.pollutionAverage}/255
- Criminalidad media: ${cityData.stats?.crimeAverage}/255
- Tráfico medio: ${cityData.stats?.trafficAverage}/255
- Modo de juego: ${cityData.gameMode}

Proporciona un análisis cognitivo profundo en formato JSON con la siguiente estructura:
{
  "archetype": "Nombre evocador del arquetipo (ej: El Ecologista Visionario, El Barón del Asfalto, etc.)",
  "title": "Título del diagnóstico",
  "summary": "Resumen perspicaz del patrón mental y estilo de toma de decisiones del alcalde",
  "playstyleCategory": "Ecológico" | "Industrial Expansivo" | "Planificador Equilibrado" | "Barón del Tránsito" | "Financiero Conservador",
  "cognitiveScores": {
    "efficiency": número 0-100,
    "sustainability": número 0-100,
    "safety": número 0-100,
    "connectivity": número 0-100,
    "financialDiscipline": número 0-100
  },
  "strengths": ["Punto fuerte 1", "Punto fuerte 2", "Punto fuerte 3"],
  "vulnerabilities": ["Punto débil 1", "Punto débil 2"],
  "tacticalAdvice": ["Consejo táctico 1", "Consejo táctico 2"],
  "alternativeStrategies": [
    {
      "title": "Nombre de estrategia alternativa a probar",
      "description": "Explicación del concepto",
      "actionPlan": "Plan paso a paso para ejecutarla"
    }
  ]
}`;

  try {
    const result = await generateCognitiveWithCascade(ai, prompt);
    return res.json({
      usedAI: true,
      modelUsed: result.modelUsed,
      analysis: result.analysis,
    });
  } catch (err: any) {
    console.warn('[Cognitive Advisor] Fallback to heuristic analyzer due to model demand:', err?.message || err);
    // Graceful fallback to heuristic engine
    const fallback = analyzePlaystyleHeuristics(cityData);
    return res.json({
      usedAI: false,
      message: 'Los servidores de IA están experimentando alta demanda momentánea. Se ha generado un diagnóstico cognitivo heurístico de alta fidelidad.',
      analysis: fallback,
    });
  }
});

// Multiplayer Real-time Room Sync (low latency room management)
app.get('/api/multiplayer/room/:roomId', (req, res) => {
  const { roomId } = req.params;
  let room = multiplayerRooms.get(roomId);

  if (!room) {
    room = {
      id: roomId,
      coMayors: new Map(),
      actions: [],
      lastUpdate: Date.now(),
    };
    multiplayerRooms.set(roomId, room);
  }

  // Cleanup inactive mayors (> 30 seconds)
  const now = Date.now();
  for (const [id, mayor] of room.coMayors.entries()) {
    if (now - mayor.lastSeen > 30000) {
      room.coMayors.delete(id);
    }
  }

  const mayorsList = Array.from(room.coMayors.values());
  res.json({
    roomId,
    coMayors: mayorsList,
    actions: room.actions.slice(-25), // last 25 collaborative actions
    serverTime: now,
  });
});

app.post('/api/multiplayer/room/:roomId/action', (req, res) => {
  const { roomId } = req.params;
  const { action, mayorId, mayorName, color } = req.body;

  let room = multiplayerRooms.get(roomId);
  if (!room) {
    room = {
      id: roomId,
      coMayors: new Map(),
      actions: [],
      lastUpdate: Date.now(),
    };
    multiplayerRooms.set(roomId, room);
  }

  const now = Date.now();

  if (mayorId) {
    room.coMayors.set(mayorId, {
      id: mayorId,
      name: mayorName || 'Co-Alcalde',
      color: color || '#38bdf8',
      lastSeen: now,
    });
  }

  if (action) {
    const actionWithMeta = {
      ...action,
      id: 'act_' + Math.random().toString(36).substring(2, 7),
      mayorId,
      mayorName,
      timestamp: now,
    };
    room.actions.push(actionWithMeta);
    if (room.actions.length > 100) room.actions.shift();
  }

  room.lastUpdate = now;

  res.json({
    success: true,
    serverTime: now,
    actionCount: room.actions.length,
  });
});

// --- Boot Vite or Static Hosting ---
async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`SimCity Classic 1989 Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
