import { CityData, CognitiveAnalysis, TileType } from '../types';
import { MAP_WIDTH, MAP_HEIGHT } from './constants';

/**
 * Client-side Heuristic Cognitive Playstyle Analyzer
 */
export function analyzePlaystyleHeuristics(city: CityData): CognitiveAnalysis {
  let resCount = 0;
  let comCount = 0;
  let indCount = 0;
  let roadCount = 0;
  let railCount = 0;
  let parkCount = 0;
  let coalCount = 0;
  let nuclearCount = 0;
  let policeCount = 0;
  let fireCount = 0;
  let unpoweredCount = 0;

  for (let y = 0; y < MAP_HEIGHT; y++) {
    for (let x = 0; x < MAP_WIDTH; x++) {
      const t = city.map?.[y]?.[x] ?? 0;
      const p = city.powered?.[y]?.[x] ?? false;

      if (t >= TileType.RESIDENTIAL_EMPTY && t <= TileType.RESIDENTIAL_HIGH) {
        resCount++;
        if (!p) unpoweredCount++;
      } else if (t >= TileType.COMMERCIAL_EMPTY && t <= TileType.COMMERCIAL_HIGH) {
        comCount++;
        if (!p) unpoweredCount++;
      } else if (t >= TileType.INDUSTRIAL_EMPTY && t <= TileType.INDUSTRIAL_HIGH) {
        indCount++;
        if (!p) unpoweredCount++;
      } else if (t === TileType.ROAD) roadCount++;
      else if (t === TileType.RAIL) railCount++;
      else if (t === TileType.PARK) parkCount++;
      else if (t === TileType.COAL_POWER) coalCount++;
      else if (t === TileType.NUCLEAR_POWER) nuclearCount++;
      else if (t === TileType.POLICE) policeCount++;
      else if (t === TileType.FIRE_STATION) fireCount++;
    }
  }

  const totalZones = resCount + comCount + indCount;

  // 1. Efficiency: low unpowered ratio, good zoning density
  const powerEfficiency = totalZones > 0 ? Math.round(((totalZones - unpoweredCount) / totalZones) * 100) : 100;
  const transitRatio = roadCount + railCount;
  const transitEfficiency = totalZones > 0 ? Math.min(100, Math.round((totalZones / Math.max(1, transitRatio)) * 60)) : 80;
  const efficiency = Math.round((powerEfficiency * 0.6) + (transitEfficiency * 0.4));

  // 2. Sustainability: clean power, parks, low pollution
  let sustainability = 75;
  if (coalCount > 0) sustainability -= coalCount * 12;
  if (nuclearCount > 0) sustainability += nuclearCount * 10;
  if (parkCount > 5) sustainability += Math.min(25, parkCount * 3);
  if (city.stats.pollutionAverage > 50) sustainability -= 20;
  sustainability = Math.max(10, Math.min(100, sustainability));

  // 3. Safety: police & fire coverage vs population
  let safety = 60;
  if (policeCount > 0) safety += 20;
  if (fireCount > 0) safety += 20;
  if (city.stats.crimeAverage > 60) safety -= 20;
  safety = Math.max(10, Math.min(100, safety));

  // 4. Connectivity: rail vs road, traffic score
  let connectivity = 70;
  if (railCount > 5) connectivity += 15;
  if (city.stats.trafficAverage > 120) connectivity -= 25;
  connectivity = Math.max(10, Math.min(100, connectivity));

  // 5. Financial discipline
  let financialDiscipline = 75;
  if (city.budget.taxRate >= 6 && city.budget.taxRate <= 8) financialDiscipline += 15;
  else if (city.budget.taxRate > 12) financialDiscipline -= 25;
  if (city.funds > 15000) financialDiscipline += 10;
  else if (city.funds < 2000) financialDiscipline -= 20;
  financialDiscipline = Math.max(10, Math.min(100, financialDiscipline));

  // Determine Archetype
  let archetype = 'El Planificador Equilibrado';
  let category: CognitiveAnalysis['playstyleCategory'] = 'Planificador Equilibrado';
  let summary = 'Muestras un estilo de juego balanceado y pragmático, cuidando tanto el crecimiento como los servicios cívicos.';

  if (sustainability > 80 && parkCount >= 6) {
    archetype = 'El Ecologista Visionario';
    category = 'Ecológico';
    summary = 'Priorizas la calidad ambiental, parques urbanos y energías limpias sobre la rápida industrialización contaminante.';
  } else if (indCount > resCount && coalCount > 0) {
    archetype = 'El Magnate de la Industria';
    category = 'Industrial Expansivo';
    summary = 'Buscas el máximo rendimiento fabril y crecimiento económico rápido, asumiendo costes ambientales.';
  } else if (railCount > roadCount * 0.5 && railCount > 8) {
    archetype = 'El Barón del Tránsito Masivo';
    category = 'Barón del Tránsito';
    summary = 'Tu obsesión es la fluidez logística y los trenes eléctricos, eliminando el tráfico vehicular.';
  } else if (financialDiscipline > 85 && city.funds > 25000) {
    archetype = 'El Estratega Fiscal Conservador';
    category = 'Financiero Conservador';
    summary = 'Gestionas las arcas públicas con disciplina suiza, acumulando reservas antes de acometer grandes obras.';
  }

  const strengths: string[] = [];
  if (efficiency > 75) strengths.push('Excelente cobertura de red eléctrica e interconexión.');
  if (sustainability > 75) strengths.push('Entorno urbano con baja polución y respeto al medio ambiente.');
  if (safety > 75) strengths.push('Servicios de policía y bomberos bien distribuidos y financiados.');
  if (connectivity > 75) strengths.push('Sistema vial fluido sin cuellos de botella severos.');
  if (strengths.length === 0) strengths.push('Capacidad de reacción rápida ante emergencias urbanas.');

  const vulnerabilities: string[] = [];
  if (unpoweredCount > 2) vulnerabilities.push(`${unpoweredCount} zonas no tienen suministro eléctrico activo.`);
  if (city.stats.pollutionAverage > 80) vulnerabilities.push('Altos niveles de polución industrial degradando el valor del suelo.');
  if (city.stats.crimeAverage > 70) vulnerabilities.push('Tasa de criminalidad elevada por falta de comisarías.');
  if (city.budget.taxRate > 9) vulnerabilities.push('Impuestos superiores al 9% sofocan la demanda de nuevas empresas.');
  if (vulnerabilities.length === 0) vulnerabilities.push('Crecimiento demográfico estancado por falta de zonas comerciales.');

  const tacticalAdvice: string[] = [];
  if (unpoweredCount > 0) tacticalAdvice.push('Tiende líneas eléctricas hacia las zonas aisladas para activar su desarrollo.');
  if (city.stats.rDemand > 40) tacticalAdvice.push('La demanda residencial es alta: planifica un nuevo cuadrante de viviendas.');
  if (city.stats.cDemand > 40) tacticalAdvice.push('Construye zonas comerciales junto a las arterias de tráfico concurridas.');
  if (city.stats.trafficAverage > 100) tacticalAdvice.push('Sustituye carreteras colapsadas por líneas de ferrocarril.');

  const alternativeStrategies = [
    {
      title: 'Modelo "Garden City" (Ciudad Jardín)',
      description: 'Crea islas residenciales rodeadas de franjas de parques (greenbelts) y trenes, alejando totalmente las fábricas.',
      actionPlan: 'Demuele carreteras redundantes, planta parques perimetrales y reubica la industria pesada.',
    },
    {
      title: 'Mega-Hub Comercial y Aeroportuario',
      description: 'Enfoca la economía en el sector servicios construyendo un Aeropuerto y un gran Estadio central.',
      actionPlan: 'Acumula $10,000, ubica el aeropuerto en un extremo despejado y rodea el centro de rascacielos C de alta densidad.',
    },
    {
      title: 'Desarrollo Marítimo Exportador',
      description: 'Aprovecha la costa construyendo un Puerto Marítimo que impulse la productividad industrial sin requerir subsidios.',
      actionPlan: 'Coloca el puerto en contacto con el agua y conecta ferrocarriles directos a las fábricas.',
    },
  ];

  return {
    archetype,
    title: `Perfil del Alcalde: ${archetype}`,
    summary,
    playstyleCategory: category,
    cognitiveScores: {
      efficiency,
      sustainability,
      safety,
      connectivity,
      financialDiscipline,
    },
    strengths,
    vulnerabilities,
    tacticalAdvice,
    alternativeStrategies,
    timestamp: new Date().toLocaleTimeString(),
  };
}
